// Package apikeys is a small client for the Shadeform API key endpoints.
//
// Those routes (`/v1/apikeys`) are deliberately absent from the published
// OpenAPI document, so the generated SDK has nothing for them: minting and
// revoking keys is a job for a signed-in person, not for an SDK or an MCP
// tool. `shade auth login` and `shade auth logout` are the only callers.
//
// This package is hand-written, not generated by Speakeasy.
package apikeys

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"
)

// Permissions a key can be minted with, as the API spells them.
const (
	PermissionPlatformRead  = "platform_read"
	PermissionPlatformWrite = "platform_write"
	PermissionBillingRead   = "billing_read"
	PermissionBillingWrite  = "billing_write"
)

// DefaultPermissions is what `shade auth login` mints: enough for every
// command the CLI has, and nothing to do with billing or account admin.
var DefaultPermissions = []string{PermissionPlatformRead, PermissionPlatformWrite}

// MaxKeysPerAccount mirrors the server's limit, so the CLI can explain a
// refusal instead of relaying a bare 400.
const MaxKeysPerAccount = 10

// Client talks to one server with one credential.
type Client struct {
	BaseURL string
	HTTP    *http.Client
	auth    func(*http.Request)
}

// NewWithBearer authenticates with an Auth0 access token. This is the login
// path: the token is used to mint a key and then forgotten.
func NewWithBearer(baseURL, accessToken string) *Client {
	return &Client{
		BaseURL: strings.TrimRight(baseURL, "/"),
		HTTP:    &http.Client{Timeout: 30 * time.Second},
		auth: func(r *http.Request) {
			r.Header.Set("Authorization", "Bearer "+accessToken)
		},
	}
}

// NewWithAPIKey authenticates with an API key. This is the logout path: a
// key revoking itself.
func NewWithAPIKey(baseURL, apiKey string) *Client {
	return &Client{
		BaseURL: strings.TrimRight(baseURL, "/"),
		HTTP:    &http.Client{Timeout: 30 * time.Second},
		auth: func(r *http.Request) {
			r.Header.Set("X-API-KEY", apiKey)
		},
	}
}

// Key is one entry of GET /v1/apikeys. The secret is never returned there.
type Key struct {
	ID          string   `json:"id"`
	Name        string   `json:"name"`
	Permissions []string `json:"permissions"`
	CreatedAt   string   `json:"created_at"`
}

// Created is the response to POST /v1/apikeys. APIKey is the only time the
// secret is ever shown; the caller stores it immediately.
type Created struct {
	ID          string   `json:"id"`
	Name        string   `json:"name"`
	APIKey      string   `json:"api_key"`
	Permissions []string `json:"permissions"`
}

// APIError is a non-2xx answer. The server's auth errors are RFC 7807 JSON
// and its apikeys handler errors are plain text; Message is whichever was
// sent, trimmed.
type APIError struct {
	Status  int
	Message string
}

func (e *APIError) Error() string {
	if e.Message == "" {
		return fmt.Sprintf("the API returned HTTP %d", e.Status)
	}
	return fmt.Sprintf("the API returned HTTP %d: %s", e.Status, e.Message)
}

// IsUnauthorized reports whether err is a 401 from the API.
func IsUnauthorized(err error) bool {
	var ae *APIError
	return errors.As(err, &ae) && ae.Status == http.StatusUnauthorized
}

// List returns the account's keys.
func (c *Client) List(ctx context.Context) ([]Key, error) {
	var resp struct {
		APIKeys []Key `json:"api_keys"`
	}
	if err := c.do(ctx, http.MethodGet, "/v1/apikeys", nil, &resp); err != nil {
		return nil, fmt.Errorf("listing API keys: %w", err)
	}
	return resp.APIKeys, nil
}

// Create mints a key. The server rejects a duplicate name and an account
// already at MaxKeysPerAccount with a 400 whose text says which.
func (c *Client) Create(ctx context.Context, name string, permissions []string) (*Created, error) {
	body := map[string]any{"name": name, "permissions": permissions}
	var created Created
	if err := c.do(ctx, http.MethodPost, "/v1/apikeys", body, &created); err != nil {
		return nil, fmt.Errorf("creating API key %q: %w", name, err)
	}
	if created.APIKey == "" {
		return nil, fmt.Errorf("creating API key %q: the response contained no key", name)
	}
	return &created, nil
}

// Delete revokes a key by ID. Revoking a key that is already gone is not an
// error here: the state the caller wanted is the state that exists.
func (c *Client) Delete(ctx context.Context, id string) error {
	err := c.do(ctx, http.MethodPost, "/v1/apikeys/"+id+"/delete", nil, nil)
	var ae *APIError
	if errors.As(err, &ae) && ae.Status == http.StatusNotFound {
		return nil
	}
	if err != nil {
		return fmt.Errorf("revoking API key %s: %w", id, err)
	}
	return nil
}

func (c *Client) do(ctx context.Context, method, path string, body any, out any) error {
	var payload io.Reader
	if body != nil {
		b, err := json.Marshal(body)
		if err != nil {
			return err
		}
		payload = bytes.NewReader(b)
	}
	req, err := http.NewRequestWithContext(ctx, method, c.BaseURL+path, payload)
	if err != nil {
		return err
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	req.Header.Set("Accept", "application/json")
	c.auth(req)

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	raw, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return err
	}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return &APIError{Status: resp.StatusCode, Message: errorMessage(raw)}
	}
	if out == nil || len(bytes.TrimSpace(raw)) == 0 {
		return nil
	}
	return json.Unmarshal(raw, out)
}

// errorMessage pulls a human-readable line out of an error body, whether it
// is RFC 7807 JSON (detail/title) or plain text.
func errorMessage(raw []byte) string {
	var problem struct {
		Title  string `json:"title"`
		Detail string `json:"detail"`
	}
	if json.Unmarshal(raw, &problem) == nil {
		if problem.Detail != "" {
			return problem.Detail
		}
		if problem.Title != "" {
			return problem.Title
		}
	}
	msg := strings.TrimSpace(string(raw))
	if len(msg) > 300 {
		msg = msg[:300] + "…"
	}
	return msg
}
